 const ad=adm?`<div class="card" style="padding:16px;margin-top:14px"><h3 style="font-weight:800">🛠 Orders (admin)</h3>${orders.filter(o=>o.status=='pending').map(o=>`<div style="margin-top:10px;border-top:1.5px solid var(--bd);padding-top:8px"><b>${esc(o.name)}</b> · ${esc(o.email)}<br>${o.kind=='tag'?'💎 '+esc(o.tag):'⭐ Premium'} · ₹${o.amt} · Txn <b>${esc(o.txn)}</b><div style="display:flex;gap:6px;margin-top:6px"><button class="btn" onclick="okOrder('${o.id}')">Approve</button><button class="ghost" onclick="noOrder('${o.id}')">Reject</button></div></div>`).join('')||'<p style="color:var(--mu);margin-top:8px">No pending orders.</p>'}</div>`:'';
