document.head.insertAdjacentHTML('beforeend','<style>.scn{position:relative;display:flex;align-items:flex-end;gap:10px;margin-top:14px;padding:10px 14px 0;border:2px solid var(--cb);border-radius:16px;background:linear-gradient(180deg,var(--c2),var(--card));overflow:hidden;box-shadow:4px 4px 0 var(--cb);min-height:130px}.sky{position:absolute;left:0;right:0;bottom:0;width:100%;height:55px;color:var(--tx);opacity:.1}.av2{position:relative;flex:none;z-index:1;overflow:visible}.av2 .bd{transform-origin:60px 130px;animation:brt 2.4s ease-in-out infinite}@keyframes brt{50%{transform:scaleY(1.025)}}.av2 .ey{transform-origin:60px 55px;animation:bl 4s infinite}@keyframes bl{0%,94%,100%{transform:scaleY(1)}97%{transform:scaleY(.1)}}.av2 .mo{display:none}.av2.idle .n,.av2.happy .h,.av2.sad .s{display:inline}.av2.happy{animation:jmp .6s ease 2}@keyframes jmp{40%{transform:translateY(-16px) rotate(-3deg)}}.av2.sad{animation:shk .5s}@keyframes shk{20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}.av2.sad .hd{transform:translateY(3px) rotate(-4deg);transform-origin:60px 80px}.sp{position:relative;z-index:1;margin-bottom:34px;font-weight:600;animation:pp .4s ease both}@keyframes pp{from{transform:scale(.6);opacity:0}}.fx{position:absolute;left:55px;top:50%;font-style:normal;font-size:1.3rem;z-index:2;animation:fly 1.1s ease-out both;animation-delay:var(--d)}@keyframes fly{from{opacity:1;transform:translate(0,0)}to{opacity:0;transform:translate(var(--x),-80px) rotate(240deg)}}</style>');
const FIG=m=>`<svg class="av2 ${m}" viewBox="0 0 120 130" width="104" height="114" aria-hidden="true"><defs><linearGradient id="sk" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#F4C7A1"/><stop offset="1" stop-color="#D49A72"/></linearGradient><linearGradient id="sh" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FF7A45"/><stop offset="1" stop-color="#E24A12"/></linearGradient></defs><g class="bd"><path d="M10 130c0-27 21-41 50-41s50 14 50 41z" fill="url(#sh)" stroke="#1A1612" stroke-width="2.5"/><path d="M44 91l16 20 16-20" fill="#fff" stroke="#1A1612" stroke-width="2"/><rect x="50" y="74" width="20" height="20" rx="8" fill="#D49A72" stroke="#1A1612" stroke-width="2"/><g class="hd"><ellipse cx="32" cy="56" rx="4.5" ry="7" fill="#E0AC85" stroke="#1A1612" stroke-width="2"/><ellipse cx="88" cy="56" rx="4.5" ry="7" fill="#E0AC85" stroke="#1A1612" stroke-width="2"/><ellipse cx="60" cy="52" rx="28" ry="31" fill="url(#sk)" stroke="#1A1612" stroke-width="2.5"/><path d="M31 47c-3-23 13-34 30-33 18 0 31 11 28 33-6-10-14-15-27-15-14 0-23 5-31 15z" fill="#2A1B14" stroke="#1A1612" stroke-width="2.5"/><g class="ey"><ellipse cx="49" cy="55" rx="5" ry="6" fill="#fff"/><ellipse cx="71" cy="55" rx="5" ry="6" fill="#fff"/><circle cx="50" cy="56" r="2.8" fill="#1A1612"/><circle cx="72" cy="56" r="2.8" fill="#1A1612"/></g><path d="M42 46q7-5 14-1M64 45q7-4 14 1" fill="none" stroke="#2A1B14" stroke-width="2.5" stroke-linecap="round"/><circle cx="42" cy="66" r="4" fill="#FF6B6B" opacity=".3"/><circle cx="78" cy="66" r="4" fill="#FF6B6B" opacity=".3"/><path class="mo n" d="M52 71q8 3 16 0" fill="none" stroke="#7A2E1A" stroke-width="2.5" stroke-linecap="round"/><path class="mo h" d="M50 68q10 13 20 0z" fill="#8B2A1A" stroke="#1A1612" stroke-width="2" stroke-linejoin="round"/><path class="mo s" d="M52 74q8-7 16 0" fill="none" stroke="#7A2E1A" stroke-width="2.5" stroke-linecap="round"/></g></g></svg>`;
const burst=e=>Array.from({length:10},(_,i)=>`<i class="fx" style="--x:${(i-5)*20}px;--d:${i*45}ms">${e}</i>`).join('');
const scn=(m,t,fx)=>`<div class="scn"><svg class="sky" viewBox="0 0 300 55" preserveAspectRatio="none"><path fill="currentColor" d="M0 55V30h22V14h18v16h16V22h24v33h20V8h22v47h26V26h20v29h24V18h20v37h20V30h22v25z"/></svg>${FIG(m)}<div class="bub sp">${t}</div>${fx||''}</div>`;
const rs=n=>'₹'+Math.round(n).toLocaleString('en-IN');
const gPick=p=>{S.g={p,l:0,cash:100000,gr:20,r:null,sw:Math.random()<.5,end:false};renderView()};
function gAns(i){const g=S.g,L=G[g.p].t[g.l],ok=g.sw?i==1:i==0,d=L[4]*1000;if(g.r)return;
 g.cash+=ok?d:-d;g.gr=Math.max(0,Math.min(100,g.gr+(ok?8:-8)));g.r={ok,why:L[3],d};renderView()}
async function gNext(){const g=S.g;g.l++;g.sw=Math.random()<.5;g.r=null;
 if(g.cash<=0||g.l>=10){g.end=true;try{if(g.gr>(U(S.uid).gbest||0))await updateDoc(doc(db,'users',S.uid),{gbest:g.gr})}catch(e){}}
 renderView()}
function gameV(){const g=S.g,best=U(S.uid).gbest||0;
 if(!g)return `<h2 style="font-size:1.4rem;font-weight:800">🎮 Business Game</h2>${scn('idle','Hello! Main tumhara business coach hoon. Raasta chuno 👇')}<p style="color:var(--mu);margin:4px 0 12px">Tumhare paas <b>₹1,00,000 virtual game money</b> hain (asli paisa nahi, sirf practice). Kya karoge? Har raaste me 10 level aur tricky faisle: sahi jawab se business badhega, galat se girega.${best?`<br>🏆 Tumhara best growth score: <b>${best}</b>`:''}</p><div class="g3">${G.map((x,i)=>`<button class="card gc" style="display:block;width:100%;text-align:left;padding:16px;margin-top:14px" onclick="gPick(${i})"><b style="font-size:1.1rem">${x.n}</b><div style="color:var(--mu);margin-top:4px">${x.d}</div><span class="stk" style="margin-top:10px">Start with ₹1,00,000 (virtual) →</span></button>`).join('')}</div>`;
 const bar=`<div class="card" style="padding:12px 16px;display:flex;gap:14px;align-items:center;flex-wrap:wrap"><div><span class="coin">🪙</span> <b>${rs(g.cash)}</b> <span style="font-size:.7rem;color:var(--mu)">virtual</span></div><div style="flex:1;min-width:120px"><div style="font-size:.75rem;color:var(--mu)">📈 Growth ${g.gr}/100 · Level ${Math.min(g.l+1,10)}/10</div><div class="bar"><i style="width:${g.gr}%"></i></div></div></div>`;
 if(g.end){const w=g.cash>0,t=g.gr>=85?'🏆 Business Titan':g.gr>=55?'🚀 Smart Founder':w?'🌱 Seekhte raho':'💥 Business band ho gaya';
  return bar+scn(w?'happy':'sad',w?'Game khatam! Shabaash 🎉':'Business band ho gaya… dobara try karo!',burst(w?'🎉':'💸'))+`<div class="g3"><div class="card gc" style="padding:20px;margin-top:14px;text-align:center"><div style="font-size:2.4rem">${w?'🎉':'💥'}</div><h2 style="font-weight:800">${t}</h2><p style="margin:8px 0;color:var(--mu)">Final virtual cash <b>${rs(g.cash)}</b> · Growth <b>${g.gr}/100</b></p><button class="btn" onclick="S.g=null;renderView()">🔁 Dobara khelo</button></div></div>`}
 const L=G[g.p].t[g.l],o=g.sw?[L[2],L[1]]:[L[1],L[2]];
 return bar+scn(g.r?(g.r.ok?'happy':'sad'):'idle',g.r?(g.r.ok?'Zabardast! Sahi faisla 💰':'Ouch! Isse seekhte hain 😅'):'Soch samajh ke chuno…',g.r?burst(g.r.ok?'🪙':'💸'):'')+`<div class="g3"><div class="card gc" style="padding:18px;margin-top:14px"><div style="font-size:.75rem;color:var(--mu);font-weight:700">${G[g.p].n}</div><h3 style="font-weight:800;margin-top:4px">${L[0]}</h3><div style="font-size:.72rem;color:var(--mu)">🎮 Game money is virtual, not real.</div>${o.map((x,i)=>`<button class="gopt" ${g.r?'disabled':''} onclick="gAns(${i})">${i?'B':'A'}) ${x}</button>`).join('')}
${g.r?`<div style="margin-top:14px;padding:12px;border-radius:12px;border:2px solid var(--cb);background:${g.r.ok?'rgba(18,183,106,.15)':'rgba(239,68,68,.15)'}"><b>${g.r.ok?'✅ Sahi! +'+rs(g.r.d):'❌ Galat! −'+rs(g.r.d)}</b><div style="margin-top:4px">${g.r.why}</div><button class="btn" style="margin-top:10px" onclick="gNext()">${g.l>=9?'Result dekho':'Agla level →'}</button></div>`:''}</div></div>`}

